import SwiftUI

struct DataConsentView: View {
    let onDecision: () -> Void
    @State private var showPolicy = false
    @EnvironmentObject private var model: PhoneAgentViewModel
    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    AgentPageIntro(title: "Allow the assistant to use this data?", subtitle: "Nothing is sent until you agree. Screen sharing must still be started separately in the system prompt.", icon: "hand.raised")
                    AgentCard {
                        VStack(alignment: .leading, spacing: 8) {
                            Text("Recipient").font(.caption).foregroundStyle(AgentPalette.secondaryText)
                            Text(PrivacyConsent.recipient(model.settings)).font(.headline)
                            Text(model.settings.endpoint).font(.footnote).foregroundStyle(AgentPalette.secondaryText).textSelection(.enabled)
                        }
                    }
                    consentSection("Screen and tasks", icon: "rectangle.on.rectangle", text: "The current screenshot, task, added instructions, and a summary of recent actions. Chat sends your question, recent chat text, and any frames you select. Screenshots may include chats, photos, names, or notifications from other apps.")
                    consentSection("Memory", icon: "bookmark", text: "With on-device memory turned on, chat sends up to 3 related memories that allow citing as text. Memory images are never sent automatically.")
                    consentSection("Files and translation", icon: "doc.text", text: "Sends the text you confirm, your formatting instructions, and the file format. With live translation on, transcript snippets are sent periodically.")
                    consentSection("Camera and voice", icon: "camera", text: "A regular camera question sends one frame. A continuous-watch question sends up to 8 sampled frames from the last 12 seconds. If you separately start continuous watch, frames, your focus instructions, and the previous observation text are sent periodically until you stop or a limit is reached. This consent does not cover video streams or microphone audio; standalone live voice and speaker separation are confirmed separately each time.")
                    Text("How the selected service stores and uses your data is governed by its privacy policy. Custom endpoints may forward data, so verify them first.")
                        .font(.footnote).foregroundStyle(AgentPalette.secondaryText)
                    AgentHelp(title: "On-device storage and keys", text: "Task and action records are stored on this device and can be cleared in Settings. Queued tasks, settings, and progress are also stored on this device and can be exported, removed, or cleared from the queue. Screenshots are not saved to task history. Your API key is stored in this device's Keychain and sent with requests to authenticate with the endpoint you configured.")
                    Button("View full data use policy") { showPolicy = true }.frame(minHeight: 44)
                    Text("You can revoke consent in Settings. Changing the endpoint or recipient requires confirming again.") .font(.caption).foregroundStyle(AgentPalette.secondaryText)
                }.padding(20)
            }.navigationTitle("AI Data Use").navigationBarTitleDisplayMode(.inline)
                .safeAreaInset(edge: .bottom) {
                    HStack(spacing: 12) {
                        Button("Not Now") { model.declineConsent(); onDecision() }.buttonStyle(AgentButtonStyle(primary: false))
                        Button("Agree and Continue") { model.acceptConsent(); onDecision() }.buttonStyle(AgentButtonStyle()).disabled(!model.modelReady)
                    }.padding(20).background(AgentPalette.background)
                }
        }.tint(AgentPalette.accent).agentSheetStyle().interactiveDismissDisabled()
            .sheet(isPresented: $showPolicy) { DataPolicyView() }
    }
    private func consentSection(_ title: String, icon: String, text: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Label(title, systemImage: icon).font(.subheadline.weight(.semibold))
            Text(text).font(.footnote).foregroundStyle(AgentPalette.secondaryText).fixedSize(horizontal: false, vertical: true)
        }.frame(maxWidth: .infinity, alignment: .leading)
    }

}

struct DataPolicyView: View {
    @Environment(\.dismiss) private var dismiss
    @EnvironmentObject private var model: PhoneAgentViewModel
    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    Text("Data Use Policy").font(.title2.weight(.semibold))
                    policy("Screen and tasks", "The screen you choose to share is used to decide the next action. While a task runs, screenshots, the task text, and a summary of recent actions are sent to the model endpoint you chose. After you stop a task, no new observation requests are made; requests already sent may have been received.")
                    policy("Provider", "Current recipient: \(PrivacyConsent.recipient(model.settings)). Endpoint: \(model.settings.endpoint.isEmpty ? "not set" : model.settings.endpoint). How data is stored, processed, and deleted depends on that service's policy. Only connect services you trust and whose policies you understand.")
                    policy("On-device storage", "The app stores settings, the current task, calibration data, action records for up to 50 tasks, and connection/calibration diagnostics. Task history contains no screenshots; live frames stay in memory while sharing. Task history and up to 20 queued tasks are kept in an on-device folder protected by system file protection and excluded from iCloud backup. The queue stores task text, settings, and progress, but no keys, screenshots, or pending actions. After a restart you must review and confirm before continuing; clearing the queue does not undo actions already taken.")
                    policy("Voice and chat", "Regular voice input uses the microphone with on-device recognition; microphone audio is never sent to the text model. You can edit the recognized text; when you submit a task or question, the text is sent to the selected service. The current chat and selected screen frames stay in memory only and can be cleared; they are not restored after the app quits. Continuous voice chat stops when you leave the page or the app goes to the background.")
                    policy("Standalone live voice", "Each session is confirmed after you review the recipient, WSS endpoint, model, voice, and separate key; raw microphone audio is then streamed for up to 5 minutes. If you also allow the camera for that session, you still turn on the preview manually and share frames one at a time, up to 20 new frames with their timestamps; no native video stream is sent. No tasks, screen sharing, history, memory, or phone actions are involved. The session ends on backgrounding, leaving the page, settings changes, errors, or system audio interruptions, and does not reconnect automatically. Audio and images are not saved to disk; reply text stays in this page's memory and can be exported. It may include text that was not fully played back and is not a verbatim recording. The service may bill for, store, or forward audio and images, so check its policy; ending a session cannot recall data already sent.")
                    policy("Web search", "Each web search is reviewed and confirmed separately. You can first confirm sending this question, the default time filter, and the current time to the currently authorized model to draft a plan of up to 3 editable searches; no frames, voice, history, memory, or search key are sent, and nothing is searched automatically. After reviewing every query and filter, you run them one by one, and each uses quota; if you cancel or one fails, sources already returned are kept and nothing is retried automatically. Queries, time filters, and the separate search key go to the selected Tavily / Brave Search service, without screenshots, audio, chat history, or memory. After sources return, you separately confirm a sourced answer; only then are the question, the confirmed search plan (including unfinished items), the completed count, and the displayed source evidence (search excerpts or body passages you selected) sent to the authorized model. The search key is never sent to the model. You open source links yourself; the app does not download full pages automatically. Results stay in this page's memory and can be exported; leaving the page or backgrounding cancels processing, and data already sent cannot be recalled. Check each service's retention / deletion policy. Search time is not publication time, and a matching citation does not guarantee accuracy. To disable search, clear the key in its settings and save.")
                    policy("Multi-round research", "Separate from the step-by-step search planner. After you confirm one question and a limit of 1–3 rounds, the assistant proposes the next round's queries, searches in order, and writes one cited answer, using at most 9 searches and 4 model requests. The model receives the question, round / time limits, queries already tried, and accumulated source excerpts; the model's queries and time filters go to the search service and may contain wording from the sources. The search key goes only to the search service and the model key only to the model; no screenshots, voice, chat history, memory, or original files are sent. It does not read full pages, follow links, or take phone actions automatically. Each request may be billed, and a finished research run does not guarantee accuracy or complete evidence. It uses at most 20 sources; citations are checked word-for-word on device, but meaning still needs human review. Errors, cancelling, backgrounding, or leaving stop further requests with no automatic retry; returned sources are kept, and data the service received cannot be recalled. Records stay in this page's memory only and must be exported; they are not restored after a restart.")
                    policy("Page text", "You can confirm, result by result, having Tavily extract a page's text. Only the full source URL (including path and query parameters) and your Tavily key are sent to the fixed extraction endpoint; no Brave or model key is used, and no question, frames, voice, history, or memory are attached. The service may charge for and store requests. Other links on the page are not followed, the app does not visit the page directly, and logins or access restrictions are not bypassed. Extracted text stays in this page's memory, up to 120,000 characters, and can be viewed or exported as TXT; it may not include the full page. Only after you select a continuous passage (up to 12,000 characters) and add it as a source can you confirm again to send that passage and other displayed material to the model; unselected text is not sent. The original search excerpt is kept and can be restored. Instructions in page text are never treated as permission to act. Leaving or backgrounding cancels, and data the service received cannot be recalled.")
                    policy("Files and notes", "Imported text, basic Office text, PDF/OCR, and audio transcripts are processed on device first; you can edit them before tapping AI Organize. With live translation on, snippets are sent periodically. The model receives the text and your instructions, never the original file or audio. Structured minutes and fishbone diagrams also send the same source text and instructions only when you tap Generate; each quote is checked against its source on device, but content and assumptions still need human review. To-dos are text only and do not create reminders automatically. Exports are generated on device and saved where you choose; JSON and minutes files include quoted source passages, and SVG captions do too. Page drafts live in memory only, so save them to memory or export them. OCR, speech, and cached spreadsheet values may contain errors, so review them.")
                    policy("On-device recordings", "Separate from transcribe-only input. Each recording requires you to confirm saving the raw audio before the system microphone permission is requested. Audio and reviewed text are stored in an on-device folder protected by system file protection and excluded from iCloud backup; you can play back, rename, delete, export, or transcribe on device and send the text to the workbench. Up to about 10 minutes each, at most 100 items / 300 MB. Recording and on-device transcription never upload audio and do not keep recording in the background; leaving the page, backgrounding, or a system interruption stops recording and saves what it can, and unfinished files are kept for review and recovery. Text goes to the model only when you separately tap Generate or Translate in the workbench. Deleting does not recall exported copies, memories saved separately, or text a service already received; speaker identity and transcripts still need human review.")
                    policy("Speaker separation", "You can pick a finished on-device recording; only after confirming the recipient, separate audio endpoint / model, and recording size each time is the full original audio uploaded with the separate key. No tasks, screen, other recordings, existing transcripts, name fields, or speaker reference samples are attached, but all voices and information in the chosen recording are sent. Limit 25 MB / 10 minutes; no automatic splitting or retry, and backgrounding, leaving the page, or settings changes stop receiving. Speakers A/B are only the service's grouping for that recording and do not prove identity; check attribution, timing, and transcript by listening back. Manual renames are your own annotations. Returned drafts stay in memory; segments you review and save, along with the service's original text, recipient / model / time, and an on-device audio checksum, are stored in the recordings folder with file protection and excluded from backup, and can be deleted alone or with the recording. The original recording and on-device transcript are not replaced. You can export TXT / JSON or send segment text to the minutes workbench; when you generate there, the selected text and your labels go to the authorized text model, without the original audio. The service may bill for, store, or forward audio; stopping or deleting local results does not recall data already sent.")
                    policy("Camera chat", "Once the camera is on and permitted, it previews in the foreground, and a regular question sends one frame. Continuous video watch keeps up to 24 compressed samples from the last 12 seconds in memory; each question or automatic observation sends 2–8 of them spread over time. Automatic watch must be started separately, runs at least 15 seconds apart, waits for each full reply, and never runs in parallel to catch up; it is limited to 10 minutes or 40 observations per session. It stops on errors, settings / permission changes, leaving the page, or backgrounding; stopping cannot recall data the service received. Turning off the camera or the mode clears samples; up to 20 observation texts stay in memory and are saved to disk only if you save them to memory. The camera does not record video or upload video streams or audio. Answers are based on samples and may miss fast changes; this is not continuous frame-by-frame video understanding.")
                    policy("On-device memory", "Text, preferences, and optional frames you choose to save are stored in an on-device folder with file protection, excluded from iCloud backup. Indexing and search happen on device. With memory turned on, related text is sent to the authorized AI service; you can disable citing for a single item, delete it, or clear everything. Saved images are for viewing on device only and are never sent automatically.")
                    policy("API keys", "Your API key is stored in this device's Keychain and used to authenticate with the configured endpoint. The app never writes keys to task records. You can clear the key in model settings and save; keys for standalone live voice, speaker separation, and search are cleared and saved in their own settings.")
                    policy("Your choices", "You can stop tasks, end screen sharing, revoke AI data consent, or delete task history and queue records. Deleting local records does not delete data a provider already received; contact the recipient under its policy. Unlocking, verification codes, and system permissions are always handled by you.")
                }.padding(20)
            }.navigationTitle("Privacy & Data").navigationBarTitleDisplayMode(.inline).toolbar { ToolbarItem(placement: .confirmationAction) { Button("Done") { dismiss() } } }
        }.tint(AgentPalette.accent).agentSheetStyle()
    }
    private func policy(_ title: String, _ text: String) -> some View {
        DisclosureGroup(title) { Text(text).font(.footnote).foregroundStyle(AgentPalette.secondaryText).fixedSize(horizontal: false, vertical: true).padding(.top, 10) }.font(.subheadline.weight(.medium)).agentPanel()
    }
}
